-- EXECUTED 2026-11-11 (exact text). Step 000b: structure capture into backup_phase1._ddl, fingerprint() function, _struct_manifest.
create table backup_phase1._ddl(seq int generated always as identity primary key, ord int not null, kind text not null, obj text, stmt text not null);
insert into backup_phase1._ddl(ord,kind,obj,stmt)
select 5,'function',p.proname::text,pg_get_functiondef(p.oid) from pg_proc p where p.pronamespace='public'::regnamespace
union all
select 10,'sequence',c.relname::text,format('create sequence public.%I as %s increment %s minvalue %s maxvalue %s start %s cache %s%s',c.relname,format_type(s.seqtypid,null),s.seqincrement,s.seqmin,s.seqmax,s.seqstart,s.seqcache,case when s.seqcycle then ' cycle' else '' end)
 from pg_class c join pg_sequence s on s.seqrelid=c.oid where c.relnamespace='public'::regnamespace and exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='a')
union all
select 20,'table',c.relname::text,format('create table public.%I (%s)',c.relname,(select string_agg(format('%I %s%s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),case a.attidentity when 'a' then ' generated always as identity' when 'd' then ' generated by default as identity' else '' end,case when a.attidentity='' and a.atthasdef then ' default '||pg_get_expr(ad.adbin,ad.adrelid) else '' end,case when a.attnotnull then ' not null' else '' end),', ' order by a.attnum) from pg_attribute a left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped))
 from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r'
union all
select 30,'data',c.relname::text,format('insert into public.%I overriding system value select * from backup_phase1.%I',c.relname,c.relname) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r'
union all
select 35,'setval',s.sequencename::text,format('select setval(%L, %s, true)','public.'||quote_ident(s.sequencename),s.last_value) from pg_sequences s where s.schemaname='public' and s.last_value is not null
union all
select case when co.contype='f' then 50 else 40 end,'constraint',co.conname::text,format('alter table public.%I add constraint %I %s',c.relname,co.conname,pg_get_constraintdef(co.oid)) from pg_constraint co join pg_class c on c.oid=co.conrelid where co.connamespace='public'::regnamespace and co.contype in ('p','u','c','f','x')
union all
select 60,'index',i.indexrelid::regclass::text,pg_get_indexdef(i.indexrelid) from pg_index i join pg_class c on c.oid=i.indrelid where c.relnamespace='public'::regnamespace and not exists(select 1 from pg_constraint k where k.conindid=i.indexrelid)
union all
select 70,'trigger',t.tgname::text,pg_get_triggerdef(t.oid) from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace='public'::regnamespace and not t.tgisinternal
union all
select 80,'rls',c.relname::text,format('alter table public.%I enable row level security',c.relname) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r' and c.relrowsecurity
union all
select 81,'rls_force',c.relname::text,format('alter table public.%I force row level security',c.relname) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r' and c.relforcerowsecurity
union all
select 85,'policy',p.polname::text,format('create policy %I on public.%I as %s for %s to %s%s%s',p.polname,c.relname,case when p.polpermissive then 'permissive' else 'restrictive' end,case p.polcmd when 'r' then 'select' when 'a' then 'insert' when 'w' then 'update' when 'd' then 'delete' else 'all' end,case when p.polroles=array[0::oid] then 'public' else (select string_agg(quote_ident(r.rolname),', ') from pg_roles r where r.oid=any(p.polroles)) end,case when p.polqual is not null then ' using ('||pg_get_expr(p.polqual,p.polrelid)||')' else '' end,case when p.polwithcheck is not null then ' with check ('||pg_get_expr(p.polwithcheck,p.polrelid)||')' else '' end) from pg_policy p join pg_class c on c.oid=p.polrelid where c.relnamespace='public'::regnamespace
union all
select 90,'view',c.relname::text,format('create view public.%I%s as %s',c.relname,case when c.reloptions is not null then ' with ('||array_to_string(c.reloptions,', ')||')' else '' end,rtrim(pg_get_viewdef(c.oid,true),';')) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='v'
union all
select 94,'revoke',c.relname::text,format('revoke all on public.%I from public, anon, authenticated, service_role',c.relname) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','v','S')
union all
select 95,'grant',c.relname::text,format('grant %s on public.%I to %s',x.privilege_type,c.relname,case when x.grantee=0 then 'public' else quote_ident(g.rolname) end) from pg_class c cross join lateral aclexplode(c.relacl) x left join pg_roles g on g.oid=x.grantee where c.relnamespace='public'::regnamespace and c.relkind in ('r','v','S') and c.relacl is not null and (x.grantee=0 or g.rolname in ('anon','authenticated','service_role'))
union all
select 97,'comment',c.relname::text,format('comment on %s public.%I is %L',case c.relkind when 'v' then 'view' else 'table' end,c.relname,obj_description(c.oid,'pg_class')) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','v') and obj_description(c.oid,'pg_class') is not null;
create function backup_phase1.fingerprint(sch text) returns table(kind text, n bigint, h text) language plpgsql as $f$
declare ns oid := (select oid from pg_namespace where nspname=sch);
begin
return query
with items as (
 select 'columns'::text k, replace(format('%s|%s|%s|%s|%s|%s|%s',c.relname,row_number() over (partition by c.oid order by a.attnum),a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,coalesce(pg_get_expr(ad.adbin,ad.adrelid),'')),sch||'.','') line from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where c.relnamespace=ns and c.relkind in ('r','v')
 union all select 'constraints', replace(format('%s|%s|%s',c.relname,co.conname,pg_get_constraintdef(co.oid)),sch||'.','') from pg_constraint co join pg_class c on c.oid=co.conrelid where co.connamespace=ns
 union all select 'indexes', replace(pg_get_indexdef(i.indexrelid),sch||'.','') from pg_index i join pg_class c on c.oid=i.indrelid where c.relnamespace=ns
 union all select 'triggers', replace(pg_get_triggerdef(t.oid),sch||'.','') from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace=ns and not t.tgisinternal
 union all select 'policies', replace(format('%s|%s|%s|%s|%s|%s',c.relname,p.polname,p.polpermissive,p.polcmd,coalesce(pg_get_expr(p.polqual,p.polrelid),''),coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'')),sch||'.','') from pg_policy p join pg_class c on c.oid=p.polrelid where c.relnamespace=ns
 union all select 'rls_flags', format('%s|%s|%s',c.relname,c.relrowsecurity,c.relforcerowsecurity) from pg_class c where c.relnamespace=ns and c.relkind='r'
 union all select 'grants', format('%s|%s|%s',c.relname,case when x.grantee=0 then 'public' else g.rolname end,x.privilege_type) from pg_class c cross join lateral aclexplode(c.relacl) x left join pg_roles g on g.oid=x.grantee where c.relnamespace=ns and c.relkind in ('r','v','S') and c.relacl is not null and (x.grantee=0 or g.rolname in ('anon','authenticated','service_role'))
 union all select 'views', replace(format('%s|%s|%s',c.relname,coalesce(array_to_string(c.reloptions,','),''),pg_get_viewdef(c.oid,true)),sch||'.','') from pg_class c where c.relnamespace=ns and c.relkind='v'
 union all select 'sequences', format('%s|%s',c.relname,format_type(s.seqtypid,null)) from pg_class c join pg_sequence s on s.seqrelid=c.oid where c.relnamespace=ns
 union all select 'column_acl', format('%s|%s',c.relname,a.attname) from pg_class c join pg_attribute a on a.attrelid=c.oid where c.relnamespace=ns and a.attacl is not null
)
select i.k, count(*)::bigint, md5(coalesce(string_agg(i.line,E'\n' order by i.line),'')) from items i group by i.k;
end $f$;
create table backup_phase1._struct_manifest as select kind,n,h from backup_phase1.fingerprint('public');
alter table backup_phase1._ddl enable row level security; alter table backup_phase1._struct_manifest enable row level security;
revoke all on all tables in schema backup_phase1 from public, anon, authenticated;
select 'ddl' src, kind, count(*)::bigint n, null::text h from backup_phase1._ddl group by kind union all select 'fingerprint', kind, n, h from backup_phase1._struct_manifest order by 1,2;
